const data = $('Prepare Client Data').first().json;
const sanitize = (val) => { if (!val) return ''; return String(val).replace(/[\n\r]/g, ' ').replace(/"/g, "'").replace(/\\/g, ''); };
return {
  business_idea: sanitize(data.business_idea), industry: sanitize(data.industry),
  location: sanitize(data.location), target_customer: sanitize(data.target_customer),
  differentiator: sanitize(data.differentiator), budget: sanitize(data.budget),
  plan_goal: sanitize(data.plan_goal), client_name: sanitize(data.client_name),
  additional_notes: sanitize(data.additional_notes),
  query: sanitize(data.business_idea) + ' ' + sanitize(data.industry) + ' competitors ' + sanitize(data.location),
};

const research = $('Growth Research').first().json.choices[0].message.content;
const basePlan = $('Basic LLM Chain').first().json.text;
const sanitize = (val) => { if (!val) return ''; return String(val).replace(/[\n\r]/g, ' ').replace(/"/g, "'").replace(/\\/g, ''); };
return { research: sanitize(research), base_plan: sanitize(basePlan) };

const s = (v) => !v ? '' : String(v).replace(/[\n\r]/g, ' ').replace(/"/g, "'").replace(/\\/g, '');
const d = $('Prepare Client Data').first().json;
const bp = s($('Basic LLM Chain').first().json.text);

const researchRaw = $('Growth Research').first().json;
const researchText = researchRaw && Array.isArray(researchRaw.choices) && researchRaw.choices[0] && researchRaw.choices[0].message ? researchRaw.choices[0].message.content : '';
const rs = s(researchText);

const braveRaw = $('Brave Search').first().json;
const braveResults = braveRaw && braveRaw.web && Array.isArray(braveRaw.web.results) ? braveRaw.web.results : [];
const bv = s(braveResults.map(r => (r.title || '') + ': ' + (r.description || '')).join(' | '));

const g = d.plan_goal || '';
let gf = '', gi = '';
if (g === 'bank-loan') {
  gf = 'Plan for a bank loan officer. Write with credibility and conservatism. Only use info explicitly provided. Do not invent details.';
  gi = 'Loan: ' + s(d.loan_amount) + '. Use: ' + s(d.loan_use) + '. Collateral: ' + s(d.assets_collateral) + '. Credit: ' + s(d.credit_standing) + '. Debt: ' + s(d.existing_debt);
} else if (g === 'investor') {
  gf = 'Plan for investors. Write with confidence and urgency. Only use info explicitly provided. Do not invent details.';
  gi = 'Background: ' + s(d.founder_background) + '. Ask: ' + s(d.funding_ask) + '. Traction: ' + s(d.current_traction) + '. Funds: ' + s(d.use_of_funds) + '. Exit: ' + s(d.exit_vision);
} else {
  gf = 'Personal roadmap. Practical tone. Address the founder directly in second person (you, your) throughout; never refer to the founder by name in third person. Only use info explicitly provided. Do not invent details.';
}

const rc = (d.current_revenue || d.years_in_business) ? 'Revenue: ' + s(d.current_revenue) + '. Years: ' + s(d.years_in_business) + '.' : '';

const rules = 'QUALITY RULES: (1) Only cite market statistics that appear in the RESEARCH or MARKET data above; use each statistic at most once, with one clearly stated meaning; if a figure\'s meaning is ambiguous, omit it rather than interpret it. (2) Include only competitors explicitly named in the RESEARCH or MARKET data; fewer verified competitors is better than a fuller table of uncertain ones. (3) State each key insight in depth exactly once, in its most relevant section; elsewhere reference it in a single short clause without re-arguing it. (4) For every revenue target or projection, show the simple bottom-up arithmetic that produces it (audience size x conversion rate x price) and state assumptions explicitly. (5) Never use em dashes anywhere; use commas, periods, or standard hyphens instead. (6) Format the SWOT as a markdown table with exactly two columns headed Category and Detail, and exactly four rows: Strengths, Weaknesses, Opportunities, Threats. Do not use an Internal versus External axis or any other column structure. (7) Do not cite software review-site star ratings, review counts, or directory scores anywhere in the plan. (8) Keep every markdown table to a maximum of four columns so it remains readable in a PDF.';

const uc = 'Enhance this base plan into a Growth-tier plan with competitive research and market data. ' + gf + ' Industry: ' + s(d.industry) + '. ' + rc + ' BASE PLAN: ' + bp + '. INPUTS: ' + s(d.client_name) + ', ' + s(d.business_idea) + ', ' + s(d.industry) + ', ' + s(d.location) + ', ' + s(d.target_customer) + ', ' + s(d.differentiator) + ', ' + s(d.budget) + '. ' + gi + ' RESEARCH: ' + rs + '. MARKET: ' + bv + '. Include all base plan sections enhanced with data. Add Market Saturation Score (1-10), SWOT, and Viability Verdict. Format all tabular data as markdown tables with each row on its own line. ' + rules;

return { payload: JSON.stringify({ model: 'anthropic/claude-sonnet-4.6', max_tokens: 8000, messages: [{ role: 'system', content: 'Professional Growth-tier business plan writer. Thorough, specific, data-driven. No filler. Do not invent details. Cite only statistics present in the provided research, each used once with one meaning. Show the arithmetic behind every financial target. Never use em dashes.' }, { role: 'user', content: uc }] }) };

let plan = '';
try { plan = $('Format Growth Output1').first().json.text || ''; } catch (e) {}
if (!plan) { try { plan = $('Basic LLM Chain').first().json.text || ''; } catch (e) {} }
const data = $('Prepare Client Data').first().json;
plan = plan.replace(/\s*\u2014\s*/g, ' - ').replace(/\u2014/g, '-');
const properName = (data.client_name || '').trim().replace(/\b\w/g, c => c.toUpperCase());
const convertTables = (src) => {
  const lines = src.split('\n');
  const out = [];
  let i = 0;
  while (i < lines.length) {
    if (/^\s*\|.*\|\s*$/.test(lines[i])) {
      const block = [];
      while (i < lines.length && /^\s*\|.*\|\s*$/.test(lines[i])) { block.push(lines[i]); i++; }
      const rows = block
        .map(l => l.trim().replace(/^\||\|$/g, '').split('|').map(c => c.trim()))
        .filter(cells => !cells.every(c => /^:?-{2,}:?$/.test(c) || c === ''));
      if (rows.length) {
        let t = '<table><thead><tr>' + rows[0].map(c => '<th>' + c + '</th>').join('') + '</tr></thead><tbody>';
        for (let r = 1; r < rows.length; r++) { t += '<tr>' + rows[r].map(c => '<td>' + c + '</td>').join('') + '</tr>'; }
        t += '</tbody></table>';
        out.push(t);
      }
    } else { out.push(lines[i]); i++; }
  }
  return out.join('\n');
};
const formatPlan = (text) => {
  return convertTables(text)
    .replace(/^### (.+)$/gm, '<h3>$1</h3>')
    .replace(/^## (\d+\. .+)$/gm, '<h2>$1</h2>')
    .replace(/^## (.+)$/gm, '<h2>$1</h2>')
    .replace(/^# (.+)$/gm, '<h1>$1</h1>')
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/^- (.+)$/gm, '<li>$1</li>')
    .replace(/(<li>.*<\/li>\n?)+/g, '<ul>$&</ul>')
    .replace(/\n\n/g, '</p><p>')
    .trim();
};
const formattedContent = formatPlan(plan);
const html = '<!DOCTYPE html><html><head><meta charset="UTF-8"><style>body{font-family:Georgia,serif;color:#1a1a2e;margin:0;padding:0}.header{background:#1e3a5f;padding:36px 48px;border-bottom:4px solid #e8b84b}.header h1{color:#fff;margin:0;font-size:28px;letter-spacing:2px;text-transform:uppercase}.meta{background:#f8f4e8;padding:16px 48px;border-left:4px solid #e8b84b;font-size:13px;color:#555}.content{padding:40px 48px;max-width:800px;margin:0 auto;line-height:1.9;font-size:15px;color:#222}h2{color:#1e3a5f;font-size:20px;margin:32px 0 12px;padding-left:12px;border-left:4px solid #e8b84b}h3{color:#1e3a5f;font-size:16px;margin:24px 0 8px}table{width:100%;border-collapse:collapse;margin:16px 0}th,td{border:1px solid #d9d2c0;padding:8px 10px;font-size:14px;text-align:left;vertical-align:top}th{background:#f8f4e8;color:#1e3a5f}ul{margin:12px 0 12px 24px}li{margin:6px 0;line-height:1.7}.footer{background:#1e3a5f;padding:20px 48px;text-align:center;margin-top:40px}.footer p{color:#a0b8d0;margin:0;font-size:12px}</style></head><body><div class="header"><h1>IDEA TO PLAN</h1><p>Business Plan - ' + (data.plan_goal_clean || 'Strategic Plan') + '</p></div><div class="meta"><strong>Prepared for:</strong> ' + properName + ' &nbsp;|&nbsp; <strong>Tier:</strong> ' + (data.package || '') + '</div><div class="content">' + formattedContent + '</div><div class="footer"><p>Built for founders ready to leap &nbsp;|&nbsp; IdeaToPlan.to</p></div></body></html>';
return [{ json: { html, client_name: properName, plan_goal_clean: data.plan_goal_clean } }];
